alter table public.credit_contracts add column if not exists signature_data text,add column if not exists consent_text text,add column if not exists signature_evidence_hash text,add column if not exists signer_ip text,add column if not exists signer_user_agent text;
update public.subscription_plans set features=features||'{"legal_templates":true}'::jsonb where code='trial';
create or replace function public.has_subscription_feature(p_feature text) returns boolean language sql stable security definer set search_path='' as $$ select coalesce((p.features->>p_feature)::boolean,false) and s.status in('trialing','active') and case when s.status='trialing' then s.trial_ends_at>now() else s.current_period_ends_at>now() end from public.organization_subscriptions s join public.subscription_plans p on p.id=s.plan_id where s.organization_id=private.current_organization_id() $$;
create or replace function public.formalize_signed_credit(p_application_id uuid,p_signature_name text,p_signature_data text,p_consent_text text,p_payment_method text,p_reference text,p_signer_ip text default null,p_signer_user_agent text default null) returns jsonb language plpgsql security definer set search_path='' as $$ declare v_result jsonb;v_contract uuid;v_hash text;begin if p_signature_data is null or p_signature_data!~'^data:image/png;base64,' or length(p_signature_data)<200 or length(p_signature_data)>350000 then raise exception 'La firma dibujada es inválida';end if;if length(btrim(coalesce(p_consent_text,'')))<20 then raise exception 'Debes registrar el consentimiento';end if;v_result:=public.formalize_credit(p_application_id,p_signature_name,p_payment_method,p_reference);v_contract:=(v_result->>'contract_id')::uuid;v_hash:=encode(extensions.digest(convert_to(p_signature_data||p_consent_text||now()::text,'UTF8'),'sha256'),'hex');update public.credit_contracts set signature_data=p_signature_data,consent_text=btrim(p_consent_text),signature_evidence_hash=v_hash,signer_ip=nullif(btrim(p_signer_ip),''),signer_user_agent=nullif(left(btrim(p_signer_user_agent),500),'') where id=v_contract;return v_result||jsonb_build_object('signature_evidence_hash',v_hash);end $$;
revoke all on function public.has_subscription_feature(text) from public,anon;grant execute on function public.has_subscription_feature(text) to authenticated;
revoke all on function public.formalize_signed_credit(uuid,text,text,text,text,text,text,text) from public,anon;grant execute on function public.formalize_signed_credit(uuid,text,text,text,text,text,text,text) to authenticated;
create or replace function public.get_my_organization() returns jsonb language sql stable security definer set search_path='' as $$ select to_jsonb(o) from public.organizations o where o.id=private.current_organization_id() $$;
revoke all on function public.get_my_organization() from public,anon;grant execute on function public.get_my_organization() to authenticated;
